INSERT INTO public.forms (id, slug, title_gu, title_hi, title_en, description_gu, description_hi, description_en, department_name_gu, department_name_hi, department_name_en, official_fee, service_fee, turnaround_days, expected_otp_count, version, myth_en, myth_gu, fact_en, fact_gu, is_active, sort_order, created_at, updated_at) VALUES ('f0000000-0000-0000-0000-000000000001', 'income_certificate', 'આવકનું પ્રમાણપત્ર', 'आय प्रमाण पत्र', 'Income Certificate', 'મામલતદાર / તાલુકા વિકાસ અધિકારી દ્વારા ૩ વર્ષ માન્યતા ધરાવતું વાર્ષિક આવક પ્રમાણપત્ર.', 'मामलतदार / तालुका विकास अधिकारी द्वारा 3 वर्ष की वैधता वाला वार्षिक आय प्रमाण पत्र।', 'Official Annual Income Certificate with 3-year validity issued by Revenue Department / Mamlatdar Office.', 'મહેસૂલ વિભાગ, ગુજરાત સરકાર (Digital Gujarat)', 'राजस्व विभाग, गुजरात सरकार (Digital Gujarat)', 'Revenue Department, Govt of Gujarat (Digital Gujarat)', 20.0, 70.0, 2, 1, 'DG-REV-2026-V1.0', 'Income Certificate in Gujarat is valid for only 1 year and must be renewed every financial year.', 'આવકનો દાખલો માત્ર ૧ વર્ષ માટે જ માન્ય રહે છે અને દર વર્ષે ફરીથી કઢાવવો પડે છે.', 'Under Gujarat Revenue Department Resolution, Income Certificates are valid for 3 Financial Years (until 31st March of the 3rd year) unless family income changes drastically.', 'ગુજરાત મહેસૂલ વિભાગના ઠરાવ મુજબ આવકનું પ્રમાણપત્ર સળંગ ૩ નાણાકીય વર્ષ (ત્રીજા વર્ષની ૩૧મી માર્ચ) સુધી સંપૂર્ણ માન્ય રહે છે.', TRUE, 1, '2026-08-28T08:52:16.903972+00:00', '2026-08-28T08:52:16.903973+00:00') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, title_gu = EXCLUDED.title_gu, title_hi = EXCLUDED.title_hi, title_en = EXCLUDED.title_en, description_gu = EXCLUDED.description_gu, description_hi = EXCLUDED.description_hi, description_en = EXCLUDED.description_en, department_name_gu = EXCLUDED.department_name_gu, department_name_hi = EXCLUDED.department_name_hi, department_name_en = EXCLUDED.department_name_en, official_fee = EXCLUDED.official_fee, service_fee = EXCLUDED.service_fee, turnaround_days = EXCLUDED.turnaround_days, expected_otp_count = EXCLUDED.expected_otp_count, version = EXCLUDED.version, myth_en = EXCLUDED.myth_en, myth_gu = EXCLUDED.myth_gu, fact_en = EXCLUDED.fact_en, fact_gu = EXCLUDED.fact_gu, is_active = EXCLUDED.is_active, sort_order = EXCLUDED.sort_order, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO public.forms (id, slug, title_gu, title_hi, title_en, description_gu, description_hi, description_en, department_name_gu, department_name_hi, department_name_en, official_fee, service_fee, turnaround_days, expected_otp_count, version, myth_en, myth_gu, fact_en, fact_gu, is_active, sort_order, created_at, updated_at) VALUES ('f0000000-0000-0000-0000-000000000002', 'ews_certificate', 'EWS (આર્થિક રીતે નબળા વર્ગ) પ્રમાણપત્ર', 'ईडब्ल्यूएस (आर्थिक रूप से कमजोर वर्ग) प्रमाण पत्र', 'Economically Weaker Section (EWS) Certificate', 'શિક્ષણ અને સરકારી નોકરીઓમાં ૧૦% અનામત માટે બિન-અનામત વર્ગનું EWS આવક અને મિલકત પ્રમાણપત્ર.', 'शिक्षा और सरकारी नौकरियों में 10% आरक्षण हेतु सामान्य वर्ग का ईडब्ल्यूएस प्रमाण पत्र।', '10% reservation certificate for General/Open category citizens under Gujarat Government criteria (≤ ₹8 Lakhs income & property criteria).', 'સામાજિક ન્યાય અને અધિકારિતા વિભાગ, ગુજરાત સરકાર', 'सामाजिक न्याय एवं अधिकारिता विभाग, गुजरात सरकार', 'Social Justice & Empowerment Department, Govt of Gujarat', 50.0, 100.0, 2, 2, 'GJ-SJE-EWS-2026-V1.0', 'EWS quota certificate is available to all backward classes including SC, ST, and SEBC/OBC.', 'EWS ૧૦% અનામત પ્રમાણપત્ર SC, ST અને OBC સહિત તમામ પછાત વર્ગના લોકો પણ મેળવી શકે છે.', 'EWS is strictly reserved for General / Open category candidates whose family income is below ₹8 Lakh per annum and who are not covered under SC/ST/SEBC quotas.', 'EWS અનામત ફક્ત એવા બિન-અનામત (General/Open) વર્ગ માટે જ છે જેઓ SC, ST કે SEBC/OBC ક્વોટામાં આવતા નથી અને વાર્ષિક આવક ૮ લાખથી ઓછી છે.', TRUE, 2, '2026-08-28T08:52:16.903973+00:00', '2026-08-28T08:52:16.903974+00:00') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, title_gu = EXCLUDED.title_gu, title_hi = EXCLUDED.title_hi, title_en = EXCLUDED.title_en, description_gu = EXCLUDED.description_gu, description_hi = EXCLUDED.description_hi, description_en = EXCLUDED.description_en, department_name_gu = EXCLUDED.department_name_gu, department_name_hi = EXCLUDED.department_name_hi, department_name_en = EXCLUDED.department_name_en, official_fee = EXCLUDED.official_fee, service_fee = EXCLUDED.service_fee, turnaround_days = EXCLUDED.turnaround_days, expected_otp_count = EXCLUDED.expected_otp_count, version = EXCLUDED.version, myth_en = EXCLUDED.myth_en, myth_gu = EXCLUDED.myth_gu, fact_en = EXCLUDED.fact_en, fact_gu = EXCLUDED.fact_gu, is_active = EXCLUDED.is_active, sort_order = EXCLUDED.sort_order, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO public.forms (id, slug, title_gu, title_hi, title_en, description_gu, description_hi, description_en, department_name_gu, department_name_hi, department_name_en, official_fee, service_fee, turnaround_days, expected_otp_count, version, myth_en, myth_gu, fact_en, fact_gu, is_active, sort_order, created_at, updated_at) VALUES ('f0000000-0000-0000-0000-000000000003', 'caste_ncl_certificate', 'નોન-ક્રીમીલેયર (NCL) / SEBC દાખલો', 'नॉन-क्रीमीलेयर (एनसीएल) / ओबीसी प्रमाण पत्र', 'Non-Creamy Layer (NCL) / SEBC Certificate', 'SEBC / OBC કેટેગરીના લાભાર્થીઓ માટે ૩ નાણાકીય વર્ષ માન્યતા ધરાવતું પેરન્ટ્સ ૩-વર્ષ આવક આધારિત નોન-ક્રીમીલેયર પ્રમાણપત્ર.', 'ओबीसी/एसईबीसी वर्ग के लिए 3 वर्ष की वैधता वाला नॉन-क्रीमीलेयर प्रमाण पत्र।', '3-year validity Non-Creamy Layer certificate for SEBC / OBC category benefits based on parents'' 3-year income history.', 'સામાજિક ન્યાય અને અધિકારિતા વિભાગ (વિકસતી જાતિ કલ્યાણ)', 'सामाजिक न्याय एवं अधिकारिता विभाग, गुजरात', 'Social Justice & Empowerment Department (DDCW Gujarat)', 20.0, 70.0, 2, 1, 'GJ-SJE-NCL-2026-V1.0', 'OBC Caste Certificate and Non-Creamy Layer (NCL) Certificate are the same document and NCL never expires.', 'જાતિનો દાખલો (Caste Certificate) અને નોન-ક્રીમીલેયર (NCL) બંને એક જ છે અને NCL ક્યારેય એક્સપાયર થતો નથી.', 'Caste certificate proves your social identity with lifetime validity, whereas NCL Certificate certifies income eligibility under creamy layer ceiling and is valid for 3 Financial Years.', 'જાતિનું પ્રમાણપત્ર આજીવન માન્ય હોય છે, જ્યારે નોન-ક્રીમીલેયર (NCL) આવક મર્યાદા દર્શાવે છે અને તે ૩ નાણાકીય વર્ષ માટે જ માન્ય રહે છે.', TRUE, 3, '2026-08-28T08:52:16.903974+00:00', '2026-08-28T08:52:16.903975+00:00') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, title_gu = EXCLUDED.title_gu, title_hi = EXCLUDED.title_hi, title_en = EXCLUDED.title_en, description_gu = EXCLUDED.description_gu, description_hi = EXCLUDED.description_hi, description_en = EXCLUDED.description_en, department_name_gu = EXCLUDED.department_name_gu, department_name_hi = EXCLUDED.department_name_hi, department_name_en = EXCLUDED.department_name_en, official_fee = EXCLUDED.official_fee, service_fee = EXCLUDED.service_fee, turnaround_days = EXCLUDED.turnaround_days, expected_otp_count = EXCLUDED.expected_otp_count, version = EXCLUDED.version, myth_en = EXCLUDED.myth_en, myth_gu = EXCLUDED.myth_gu, fact_en = EXCLUDED.fact_en, fact_gu = EXCLUDED.fact_gu, is_active = EXCLUDED.is_active, sort_order = EXCLUDED.sort_order, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO public.forms (id, slug, title_gu, title_hi, title_en, description_gu, description_hi, description_en, department_name_gu, department_name_hi, department_name_en, official_fee, service_fee, turnaround_days, expected_otp_count, version, myth_en, myth_gu, fact_en, fact_gu, is_active, sort_order, created_at, updated_at) VALUES ('f0000000-0000-0000-0000-000000000004', 'land_records_7_12', '૭/૧૨ અને ૮-અ જમીન રેકોર્ડ નકલ (AnyRoR)', '7/12 एवं 8-अ भूमि रिकॉर्ड नकल (AnyRoR)', '7/12 & 8-A Land Record Extracts (AnyRoR)', 'ગુજરાતના કોઈપણ મહેસૂલી ગામના અધિકૃત ડિજિટલ સહીવાળા ૭/૧૨, ૮-અ અને હક્ક પત્રક ૬ ઉતારા.', 'गुजरात के किसी भी गांव के डिजिटल हस्ताक्षरित 7/12, 8-ए नकल।', 'Digitally signed official certified land records 7/12, 8-A & VF-6 from AnyRoR Gujarat with official QR validation.', 'મહેસૂલ વિભાગ - જમીન દફતર અને ઇ-ધરા (AnyRoR)', 'राजस्व विभाग - भूमि अभिलेख (AnyRoR)', 'Revenue Dept - Land Records & E-Dhara (AnyRoR Gujarat)', 15.0, 65.0, 1, 1, 'ANYROR-GJ-2026-V1.0', 'Online AnyRoR 7/12 copies cannot be accepted by banks for KCC or loan mortgages without manual Talati physical stamp.', 'ઓનલાઇન ડાઉનલોડ કરેલી AnyRoR ૭/૧૨ નકલ પર તલાટીનો સિક્કો ન હોય તો બેંક લોન માટે માન્ય ગણાતી નથી.', 'Digitally signed AnyRoR 7/12 records with Gujarat Govt QR code and barcode watermark have 100% legal validity under Sec 65B of Indian Evidence Act across all banks, registries, and courts.', 'ક્યુઆર કોડ અને ડિજિટલ સહીવાળી AnyRoR ૭/૧૨ નકલ તમામ રાષ્ટ્રીયકૃત બેંકો, દસ્તાવેજ રજીસ્ટ્રાર અને કોર્ટમાં કાયદેસર ૧૦૦% માન્ય ગણાય છે.', TRUE, 4, '2026-08-28T08:52:16.903975+00:00', '2026-08-28T08:52:16.903976+00:00') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, title_gu = EXCLUDED.title_gu, title_hi = EXCLUDED.title_hi, title_en = EXCLUDED.title_en, description_gu = EXCLUDED.description_gu, description_hi = EXCLUDED.description_hi, description_en = EXCLUDED.description_en, department_name_gu = EXCLUDED.department_name_gu, department_name_hi = EXCLUDED.department_name_hi, department_name_en = EX