INSERT INTO public.forms (id, slug, title_gu, title_hi, title_en, description_gu, description_hi, description_en, department_name_gu, department_name_hi, department_name_en, official_fee, service_fee, turnaround_days, expected_otp_count, version, myth_en, myth_gu, fact_en, fact_gu, is_active, sort_order, created_at, updated_at) VALUES ('f0000000-0000-0000-0000-000000000005', 'driving_licence_rto', 'ડ્રાઇવિંગ / લર્નિંગ લાયસન્સ સહાયતા (RTO સારથી)', 'ड्राइविंग / लर्निंग लाइसेंस सहायता (RTO सारथी)', 'Driving / Learner Licence Assistance (Sarathi RTO)', 'લર્નિંગ લાયસન્સ (ફેસલેસ હોમ ટેસ્ટ), નવું DL સ્લોટ બુકિંગ, કેટેગરી ઉમેરો, રીન્યુઅલ અને ડુપ્લીકેટ લાયસન્સ સહાયતા.', 'लर्निंग लाइसेंस (फेसलेस ऑनलाइन टेस्ट), स्थायी डीएल स्लॉट बुकिंग एवं नवीनीकरण सहायता।', 'End-to-end Sarathi Parivahan portal filing, contactless LL test setup, vehicle class addition, and DL appointment booking.', 'વાહન વ્યવહાર કમિશનર કચેરી, ગુજરાત સરકાર (Sarathi 4.0)', 'परिवहन आयुक्त कार्यालय, गुजरात સરકાર (Sarathi 4.0)', 'Transport Department, Govt of Gujarat (Sarathi Parivahan)', 150.0, 1000.0, 2, 2, 'SARATHI-GJ-2026-V1.0', 'You must physically visit the RTO office and wait in long queues for hours just to take the Learner Licence test.', 'લર્નિંગ લાયસન્સની પરીક્ષા આપવા માટે ફરજિયાત RTO કચેરીએ જઈને આખો દિવસ લાઈનમાં ઊભા રહેવું પડે છે.', 'Under Gujarat''s Contactless Faceless RTO (Sarathi 4.0), you can take the online LL computer theory test from home via Aadhaar facial recognition and download your LL immediately upon passing.', 'ગુજરાત પરિવહન વિભાગની ફેસલેસ RTO પહેલ હેઠળ તમે ઘરે બેઠા મોબાઈલ/લેપટોપ પરથી આધાર ફેસ ઓથેન્ટિકેશનથી ઓનલાઇન LL પરીક્ષા આપીને તુરંત લાયસન્સ ડાઉનલોડ કરી શકો છો.', TRUE, 5, '2026-08-28T08:52:16.903977+00:00', '2026-08-28T08:52:16.903977+00:00') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, title_gu = EXCLUDED.title_gu, title_hi = EXCLUDED.title_hi, title_en = EXCLUDED.title_en, description_gu = EXCLUDED.description_gu, description_hi = EXCLUDED.description_hi, description_en = EXCLUDED.description_en, department_name_gu = EXCLUDED.department_name_gu, department_name_hi = EXCLUDED.department_name_hi, department_name_en = EXCLUDED.department_name_en, official_fee = EXCLUDED.official_fee, service_fee = EXCLUDED.service_fee, turnaround_days = EXCLUDED.turnaround_days, expected_otp_count = EXCLUDED.expected_otp_count, version = EXCLUDED.version, myth_en = EXCLUDED.myth_en, myth_gu = EXCLUDED.myth_gu, fact_en = EXCLUDED.fact_en, fact_gu = EXCLUDED.fact_gu, is_active = EXCLUDED.is_active, sort_order = EXCLUDED.sort_order, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO public.forms (id, slug, title_gu, title_hi, title_en, description_gu, description_hi, description_en, department_name_gu, department_name_hi, department_name_en, official_fee, service_fee, turnaround_days, expected_otp_count, version, exam_year, bulletin_version, myth_en, myth_gu, fact_en, fact_gu, is_active, sort_order, created_at, updated_at) VALUES ('f0000000-0000-0000-0000-000000000006', 'neet_exam', 'NEET UG મેડિકલ પ્રવેશ પરીક્ષા ૨૦૨૬', 'नीट यूजी मेडिकल प्रवेश परीक्षा 2026', 'NEET UG Medical Entrance Exam Registration', 'NTA NEET UG 2026 પ્રવેશ પરીક્ષા ફોર્મ. કેટેગરી મુજબ સરકારી ફી: જનરલ (UR): ₹૧,૭૦૦ | EWS / OBC-NCL: ₹૧,૬૦૦ | SC / ST / PwBD / તૃતીય પંથી: ₹૧,૦૦૦.', 'NTA नीट यूजी 2026 परीक्षा फॉर्म। श्रेणीवार शुल्क: सामान्य (UR): ₹1,700 | EWS / OBC-NCL: ₹1,600 | SC / ST / PwBD / तृतीय पंथी: ₹1,000.', 'NTA NEET UG 2026 Registration. Category-Wise Fee Structure: General (UR): ₹1,700 | General-EWS / OBC-NCL: ₹1,600 | SC / ST / PwBD / Third Gender: ₹1,000.', 'નેશનલ ટેસ્ટિંગ એજન્સી (NTA) / કેન્દ્રીય આરોગ્ય મંત્રાલય', 'राष्ट्रीय परीक्षा एजेंसी (NTA)', 'National Testing Agency (NTA, Govt of India)', 1700.0, 200.0, 2, 2, 'NEET-UG-2026-NTA-V1.0', 2026, 'NTA-NEET-UG-2026-IB-REV1', 'If a candidate chooses Gujarati medium for NEET UG, the question booklet will only be in Gujarati and English questions will not be available.', 'જો NEET પરીક્ષામાં ગુજરાતી માધ્યમ પસંદ કરીએ તો પ્રશ્નપત્ર ફક્ત ગુજરાતીમાં જ આવશે અને અંગ્રેજી ભાષાંતર જોવા નહીં મળે.', 'If Gujarati medium is selected, NTA provides a Bilingual Question Booklet with every question printed in both Gujarati and English side-by-side on the same page.', 'જો તમે ગુજરાતી માધ્યમ પસંદ કરો છો તો NTA દ્વારા આપવામાં આવતી પ્રશ્નપુસ્તિકામાં દરેક પ્રશ્ન ગુજરાતી અને અંગ્રેજી બંને ભાષામાં સામસામે છપાયેલો હોય છે.', TRUE, 6, '2026-08-28T08:52:16.903978+00:00', '2026-08-28T08:52:16.903979+00:00') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, title_gu = EXCLUDED.title_gu, title_hi = EXCLUDED.title_hi, title_en = EXCLUDED.title_en, description_gu = EXCLUDED.description_gu, description_hi = EXCLUDED.description_hi, description_en = EXCLUDED.description_en, department_name_gu = EXCLUDED.department_name_gu, department_name_hi = EXCLUDED.department_name_hi, department_name_en = EXCLUDED.department_name_en, official_fee = EXCLUDED.official_fee, service_fee = EXCLUDED.service_fee, turnaround_days = EXCLUDED.turnaround_days, expected_otp_count = EXCLUDED.expected_otp_count, version = EXCLUDED.version, exam_year = EXCLUDED.exam_year, bulletin_version = EXCLUDED.bulletin_version, myth_en = EXCLUDED.myth_en, myth_gu = EXCLUDED.myth_gu, fact_en = EXCLUDED.fact_en, fact_gu = EXCLUDED.fact_gu, is_active = EXCLUDED.is_active, sort_order = EXCLUDED.sort_order, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
