INSERT INTO public.form_fields (id, form_id, field_key, step_section, field_type, label_gu, label_hi, label_en, options_json, is_required, sort_order, created_at, updated_at) VALUES ('c034e391-03bd-4e1f-9f89-4b7f1a06698e', 'f0000000-0000-0000-0000-000000000005', 'licence_type', 'licence_service', 'select', 'કઈ લાયસન્સ સેવા જોઈએ છે?', 'लाइसेंस सेवा प्रकार', 'What Licence Service Do You Need?', '[{"value": "learner", "label_gu": "\u0aa8\u0ab5\u0ac1\u0a82 \u0ab2\u0ab0\u0acd\u0aa8\u0abf\u0a82\u0a97 \u0ab2\u0abe\u0aaf\u0ab8\u0aa8\u0acd\u0ab8 (LLR - \u0a98\u0ab0\u0ac7 \u0aac\u0ac7\u0aa0\u0abe \u0aab\u0ac7\u0ab8\u0ab2\u0ac7\u0ab8 \u0a93\u0aa8\u0ab2\u0abe\u0a87\u0aa8 \u0a9f\u0ac7\u0ab8\u0acd\u0a9f)", "label_hi": "\u0928\u092f\u093e \u0932\u0930\u094d\u0928\u093f\u0902\u0917 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 (\u0911\u0928\u0932\u093e\u0907\u0928 \u091f\u0947\u0938\u094d\u091f)", "label_en": "New Learner Licence (LLR - Contactless Home Test)"}, {"value": "permanent", "label_gu": "\u0a95\u0abe\u0aaf\u0aae\u0ac0 \u0aa1\u0acd\u0ab0\u0abe\u0a87\u0ab5\u0abf\u0a82\u0a97 \u0ab2\u0abe\u0aaf\u0ab8\u0aa8\u0acd\u0ab8 (DL \u0a9f\u0ac7\u0ab8\u0acd\u0a9f \u0ab8\u0acd\u0ab2\u0acb\u0a9f \u0aac\u0ac1\u0a95\u0abf\u0a82\u0a97)", "label_hi": "\u0938\u094d\u0925\u093e\u092f\u0940 \u0921\u094d\u0930\u093e\u0907\u0935\u093f\u0902\u0917 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 (\u0921\u0940\u090f\u0932)", "label_en": "New Permanent Driving Licence (DL Slot Booking)"}, {"value": "class_addition", "label_gu": "\u0ab5\u0abe\u0ab9\u0aa8 \u0a95\u0ac7\u0a9f\u0ac7\u0a97\u0ab0\u0ac0 \u0a89\u0aae\u0ac7\u0ab0\u0acb (\u0aa6\u0abe.\u0aa4. \u0aac\u0abe\u0a87\u0a95\u0aae\u0abe\u0a82\u0aa5\u0ac0 \u0a95\u0abe\u0ab0 \u0a89\u0aae\u0ac7\u0ab0\u0acb)", "label_hi": "\u0935\u093e\u0939\u0928 \u0936\u094d\u0930\u0947\u0923\u0940 \u091c\u094b\u0921\u093c\u0947\u0902 (Endorsement)", "label_en": "Addition of Class of Vehicle (Endorsement)"}, {"value": "renewal", "label_gu": "\u0ab2\u0abe\u0aaf\u0ab8\u0aa8\u0acd\u0ab8 \u0ab0\u0ac0\u0aa8\u0acd\u0aaf\u0ac1\u0a85\u0ab2 (Renewal of Expired DL)", "label_hi": "\u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0928\u0935\u0940\u0928\u0940\u0915\u0930\u0923", "label_en": "Licence Renewal (Expired DL)"}, {"value": "duplicate", "label_gu": "\u0aa1\u0ac1\u0aaa\u0acd\u0ab2\u0ac0\u0a95\u0ac7\u0a9f \u0ab2\u0abe\u0aaf\u0ab8\u0aa8\u0acd\u0ab8 (\u0a96\u0acb\u0ab5\u0abe\u0a88 \u0a97\u0aaf\u0ac7\u0ab2/\u0aa4\u0ac2\u0a9f\u0ac0 \u0a97\u0aaf\u0ac7\u0ab2 \u0ab2\u0abe\u0aaf\u0ab8\u0aa8\u0acd\u0ab8)", "label_hi": "\u0921\u0941\u092a\u094d\u0932\u0940\u0915\u0947\u091f \u0932\u093e\u0907\u0938\u0947\u0902\u0938", "label_en": "Duplicate Driving Licence"}]', TRUE, 14, '2026-08-28T08:52:16.905670+00:00', '2026-08-28T08:52:16.905670+00:00') ON CONFLICT (id) DO UPDATE SET form_id = EXCLUDED.form_id, field_key = EXCLUDED.field_key, step_section = EXCLUDED.step_section, field_type = EXCLUDED.field_type, label_gu = EXCLUDED.label_gu, label_hi = EXCLUDED.label_hi, label_en = EXCLUDED.label_en, options_json = EXCLUDED.options_json, is_required = EXCLUDED.is_required, sort_order = EXCLUDED.sort_order, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO public.form_fields (id, form_id, field_key, step_section, field_type, label_gu, label_hi, label_en, options_json, is_required, sort_order, created_at, updated_at) VALUES ('d4fcf182-b4a7-41ab-8b80-618ee759029a', 'f0000000-0000-0000-0000-000000000005', 'vehicle_class', 'licence_service', 'select', 'વાહન ક્લાસ / કેટેગરી', 'वाहन श्रेणी', 'Vehicle Class Category', '[{"value": "MCWG", "label_gu": "\u0aae\u0acb\u0a9f\u0ab0 \u0ab8\u0abe\u0aaf\u0a95\u0ab2 \u0a97\u0abf\u0aaf\u0ab0\u0ab5\u0abe\u0ab3\u0ac0 (MCWG - \u0aac\u0abe\u0a87\u0a95 / \u0a9f\u0ac1-\u0ab5\u0acd\u0ab9\u0ac0\u0ab2\u0ab0)", "label_hi": "\u0926\u094b\u092a\u0939\u093f\u092f\u093e \u0917\u093f\u092f\u0930 \u0938\u0939\u093f\u0924 (MCWG)", "label_en": "Motorcycle with Gear (MCWG - Two Wheeler)"}, {"value": "LMV", "label_gu": "\u0ab2\u0abe\u0a87\u0a9f \u0aae\u0acb\u0a9f\u0ab0 \u0ab5\u0acd\u0ab9\u0ac0\u0a95\u0ab2 (LMV - \u0a95\u0abe\u0ab0 / \u0aab\u0acb\u0ab0-\u0ab5\u0acd\u0ab9\u0ac0\u0ab2\u0ab0)", "label_hi": "\u0939\u0932\u094d\u0915\u093e \u092e\u094b\u091f\u0930 \u0935\u093e\u0939\u0928 (LMV - \u0915\u093e\u0930)", "label_en": "Light Motor Vehicle (LMV - Car)"}, {"value": "MCWG_LMV", "label_gu": "\u0aac\u0abe\u0a87\u0a95 + \u0a95\u0abe\u0ab0 \u0aac\u0a82\u0aa8\u0ac7 (MCWG + LMV \u0ab8\u0a82\u0aaf\u0ac1\u0a95\u0acd\u0aa4)", "label_hi": "\u0926\u094b\u092a\u0939\u093f\u092f\u093e + \u0915\u093e\u0930 \u0926\u094b\u0928\u094b\u0902", "label_en": "Both Two-Wheeler + Car (MCWG + LMV)"}, {"value": "MCWOG", "label_gu": "\u0a97\u0abf\u0aaf\u0ab0 \u0ab5\u0a97\u0ab0\u0aa8\u0ac1\u0a82 \u0ab8\u0acd\u0a95\u0ac2\u0a9f\u0ab0 (MCWOG - \u0a8f\u0a95\u0acd\u0a9f\u0abf\u0ab5\u0abe/\u0a9c\u0acd\u0aaf\u0ac1\u0aaa\u0abf\u0a9f\u0ab0)", "label_hi": "\u0938\u094d\u0915\u0942\u091f\u0930 \u092c\u093f\u0928\u093e \u0917\u093f\u092f\u0930", "label_en": "Motorcycle without Gear (Scooter)"}]', TRUE, 15, '2026-08-28T08:52:16.905675+00:00', '2026-08-28T08:52:16.905675+00:00') ON CONFLICT (id) DO UPDATE SET form_id = EXCLUDED.form_id, field_key = EXCLUDED.field_key, step_section = EXCLUDED.step_section, field_type = EXCLUDED.field_type, label_gu = EXCLUDED.label_gu, label_hi = EXCLUDED.label_hi, label_en = EXCLUDED.label_en, options_json = EXCLUDED.options_json, is_required = EXCLUDED.is_required, sort_order = EXCLUDED.sort_order, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
