INSERT INTO public.service_documents (id, form_id, document_type_key, name_en, name_gu, name_hi, required_level, accepted_formats, max_size_mb, why_needed_en, why_needed_gu, why_needed_hi, where_to_get_en, where_to_get_gu, where_to_get_hi, source_authority_en, source_authority_gu, source_authority_hi, sort_order, is_active, created_at) VALUES ('95700384-5d27-4210-b132-23169ffc7727', 'f0000000-0000-0000-0000-000000000001', 'aadhaar_card', 'Aadhaar Card (Applicant / Head of Family)', 'અરજદારનું આધાર કાર્ડ', 'आधार कार्ड (आवेदक)', 'mandatory', '["PDF", "JPG", "PNG"]', 5, 'Mandatory identity and biometric KYC proof across Gujarat digital revenue portal.', 'ગુજરાત મહેસૂલ પોર્ટલ પર ઓળખ અને e-KYC ચકાસણી માટે ફરજિયાત.', 'डिजिटल पहचान एवं ई-केवाईसी हेतु अनिवार्य।', 'Download digital e-Aadhaar from UIDAI Portal (eaadhaar.uidai.gov.in) or scan physical card.', 'UIDAI પોર્ટલ પરથી ઓનલાઇન અથવા આધાર કેન્દ્ર / અસલ કાર્ડ સ્કેન.', 'यूआईडीएआई पोर्टल अथवा मूल आधार कार्ड।', 'Unique Identification Authority of India (UIDAI)', 'યુઆઈડીએઆઈ (UIDAI) ભારત સરકાર', 'यूआईडीएआई भारत सरकार', 1, TRUE, '2026-08-28T08:52:16.905004+00:00') ON CONFLICT (id) DO UPDATE SET form_id = EXCLUDED.form_id, document_type_key = EXCLUDED.document_type_key, name_en = EXCLUDED.name_en, name_gu = EXCLUDED.name_gu, name_hi = EXCLUDED.name_hi, required_level = EXCLUDED.required_level, accepted_formats = EXCLUDED.accepted_formats, max_size_mb = EXCLUDED.max_size_mb, why_needed_en = EXCLUDED.why_needed_en, why_needed_gu = EXCLUDED.why_needed_gu, why_needed_hi = EXCLUDED.why_needed_hi, where_to_get_en = EXCLUDED.where_to_get_en, where_to_get_gu = EXCLUDED.where_to_get_gu, where_to_get_hi = EXCLUDED.where_to_get_hi, source_authority_en = EXCLUDED.source_authority_en, source_authority_gu = EXCLUDED.source_authority_gu, source_authority_hi = EXCLUDED.source_authority_hi, sort_order = EXCLUDED.sort_order, is_active = EXCLUDED.is_active, created_at = EXCLUDED.created_at;
INSERT INTO public.service_documents (id, form_id, document_type_key, name_en, name_gu, name_hi, required_level, accepted_formats, max_size_mb, why_needed_en, why_needed_gu, why_needed_hi, where_to_get_en, where_to_get_gu, where_to_get_hi, source_authority_en, source_authority_gu, source_authority_hi, sort_order, is_active, created_at) VALUES ('14818d1c-540a-415d-aacf-1afaed1bbf40', 'f0000000-0000-0000-0000-000000000001', 'ration_card', 'Ration Card (All Family Members Page)', 'રેશન કાર્ડ (તમામ સભ્યોના નામવાળું પાનું)', 'राशन कार्ड (पारिवारिक विवरण)', 'mandatory', '["PDF", "JPG", "PNG"]', 5, 'Verifies family tree composition to establish total combined family income.', 'કુટુંબના તમામ સભ્યોની ગણતરી અને સંયુક્ત વાર્ષિક આવક સ્થાપિત કરવા માટે.', 'परिवार के सदस्यों एवं कुल पारिवारिक आय सत्यापन हेतु।', 'Physical ration card booklet issued by Food & Civil Supplies Department Gujarat / Digital Gujarat barcoded copy.', 'અન્ન અને નાગરિક પુરવઠા વિભાગ ગુજરાત દ્વારા જારી રેશન કાર્ડ.', 'खाद्य एवं नागरिक आपूर्ति विभाग द्वारा प्रदत्त राशन कार्ड।', 'Food & Civil Supplies Dept, Govt of Gujarat', 'અન્ન અને નાગરિક પુરવઠા વિભાગ, ગુજરાત', 'नागरिक आपूर्ति विभाग गुजरात', 2, TRUE, '2026-08-28T08:52:16.905008+00:00') ON CONFLICT (id) DO UPDATE SET form_id = EXCLUDED.form_id, document_type_key = EXCLUDED.document_type_key, name_en = EXCLUDED.name_en, name_gu = EXCLUDED.name_gu, name_hi = EXCLUDED.name_hi, required_level = EXCLUDED.required_level, accepted_formats = EXCLUDED.accepted_formats, max_size_mb = EXCLUDED.max_size_mb, why_needed_en = EXCLUDED.why_needed_en, why_needed_gu = EXCLUDED.why_needed_gu, why_needed_hi = EXCLUDED.why_needed_hi, where_to_get_en = EXCLUDED.where_to_get_en, where_to_get_gu = EXCLUDED.where_to_get_gu, where_to_get_hi = EXCLUDED.where_to_get_hi, source_authority_en = EXCLUDED.source_authority_en, source_authority_gu = EXCLUDED.source_authority_gu, source_authority_hi = EXCLUDED.source_authority_hi, sort_order = EXCLUDED.sort_order, is_active = EXCLUDED.is_active, created_at = EXCLUDED.created_at;
INSERT INTO public.service_documents (id, form_id, document_type_key, name_en, name_gu, name_hi, required_level, accepted_formats, max_size_mb, why_needed_en, why_needed_gu, why_needed_hi, where_to_get_en, where_to_get_gu, where_to_get_hi, source_authority_en, source_authority_gu, source_authority_hi, sort_order, is_active, created_at) VALUES ('d969d159-c6fe-4c59-beb0-cf93dfecc674', 'f0000000-0000-0000-0000-000000000001', 'income_proof', 'Income Proof (Talati Report / Salary Slip / Form 16 / ITR)', 'આવકનો સત્તાવાર પુરાવો (તલાટી પંચનામું / પગાર સ્લિપ / ફોર્મ-૧૬ / ITR)', 'आय प्रमाण (तलाटी रिपोर्ट / वेतन पर्ची / आईटीआर)', 'mandatory', '["PDF", "JPG", "PNG"]', 5, 'Official documentary justification of applicant''s declared annual financial income.', 'અરજદાર દ્વારા દર્શાવેલ વાર્ષિક આવકની કાયદેસર ખરાઈ માટે.', 'वार्षिक आय के प्रमाणिक सत्यापन हेतु।', 'Village Talati Mantri (Rural) / Employer Salary Certificate / IT Department ITR acknowledgement (Urban).', 'ગામના તલાટી કમ મંત્રીનો દાખલો (ગ્રામ્ય) અથવા નોકરીની પગાર સ્લિપ / ITR રિટર્ન (શહેરી).', 'तलाटी कार्यालय अथवा नियोक्ता वेतन प्रमाण पत्र / आईटीआर।', 'Revenue Talati / Income Tax Dept / Employer', 'મહેસૂલ તલાટી / ઇન્કમ ટેક્સ વિભાગ / એમ્પ્લોયર', 'राजस्व तलाटी / आयकर विभाग', 3, TRUE, '2026-08-28T08:52:16.905012+00:00') ON CONFLICT (id) DO UPDATE SET form_id = EXCLUDED.form_id, document_type_key = EXCLUDED.document_type_key, name_en = EXCLUDED.name_en, name_gu = EXCLUDED.name_gu, name_hi = EXCLUDED.name_hi, required_level = EXCLUDED.required_level, accepted_formats = EXCLUDED.accepted_formats, max_size_mb = EXCLUDED.max_size_mb, why_needed_en = EXCLUDED.why_needed_en, why_needed_gu = EXCLUDED.why_needed_gu, why_needed_hi = EXCLUDED.why_needed_hi, where_to_get_en = EXCLUDED.where_to_get_en, where_to_get_gu = EXCLUDED.where_to_get_gu, where_to_get_hi = EXCLUDED.where_to_get_hi, source_authority_en = EXCLUDED.source_authority_en, source_authority_gu = EXCLUDED.source_authority_gu, source_authority_hi = EXCLUDED.source_authority_h