INSERT INTO public.service_documents (id, form_id, document_type_key, name_en, name_gu, name_hi, required_level, condition_rule, accepted_formats, max_size_mb, why_needed_en, why_needed_gu, why_needed_hi, where_to_get_en, where_to_get_gu, where_to_get_hi, source_authority_en, source_authority_gu, source_authority_hi, sort_order, is_active, created_at) VALUES ('ece8a1e7-8780-4867-883a-589557bf3acb', 'f0000000-0000-0000-0000-000000000005', 'form_1a_medical', 'Form 1-A Medical Fitness Certificate (By Registered Medical Practitioner)', 'ફોર્મ ૧-એ મેડિકલ ફિટનેસ સર્ટિફિકેટ (૪૦ વર્ષથી વધુ ઉંમર અથવા કોમર્શિયલ વાહન માટે)', 'फॉर्म 1-ए मेडिकल फिटनेस प्रमाण पत्र', 'conditional', '{"field": "applicant_age", "op": "gte", "value": 40}', '["PDF", "JPG", "PNG"]', 5, 'Statutory requirement under Central Motor Vehicle Rules for applicants aged 40+ or transport licences.', 'મોટર વ્હીકલ નિયમો મુજબ ૪૦ વર્ષથી વધુ ઉંમરના અરજદારો માટે મેડિકલ સર્ટિફિકેટ જરૂરી છે.', '40 वर्ष से अधिक आयु अथवा व्यावसायिक वाहन हेतु।', 'Any Registered MBBS Medical Practitioner / Govt Hospital Doctor.', 'કોઈપણ માન્ય MBBS ડોક્ટર અથવા સરકારી હોસ્પિટલ.', 'पंजीकृत चिकित्सक / सरकारी अस्पताल।', 'Registered Medical Practitioner (MBBS)', 'માન્ય તબીબી અધિકારી (MBBS)', 'पंजीकृत चिकित्सक', 4, TRUE, '2026-08-28T08:52:16.905075+00:00') ON CONFLICT (id) DO UPDATE SET form_id = EXCLUDED.form_id, document_type_key = EXCLUDED.document_type_key, name_en = EXCLUDED.name_en, name_gu = EXCLUDED.name_gu, name_hi = EXCLUDED.name_hi, required_level = EXCLUDED.required_level, condition_rule = EXCLUDED.condition_rule, accepted_formats = EXCLUDED.accepted_formats, max_size_mb = EXCLUDED.max_size_mb, why_needed_en = EXCLUDED.why_needed_en, why_needed_gu = EXCLUDED.why_needed_gu, why_needed_hi = EXCLUDED.why_needed_hi, where_to_get_en = EXCLUDED.where_to_get_en, where_to_get_gu = EXCLUDED.where_to_get_gu, where_to_get_hi = EXCLUDED.where_to_get_hi, source_authority_en = EXCLUDED.source_authority_en, source_authority_gu = EXCLUDED.source_authority_gu, source_authority_hi = EXCLUDED.source_authority_hi, sort_order = EXCLUDED.sort_order, is_active = EXCLUDED.is_active, created_at = EXCLUDED.created_at;
